def stringComposition(k: int, text: str) -> list[str]:
    """Return the k-mer composition of text, including repeated k-mers (BA3A)."""
    # TODO: Write your code here.

    kmers = []
    for i in range(len(text)-k+1):
        kmers.append(text[i:i+k])

    return sorted(kmers)

